import base64, json, math, time
import numpy as np, torch
import os as _osx; _osx.system("python -m pip uninstall -y -q torchao 2>/dev/null")
from transformers import AutoTokenizer, AutoModelForCausalLM
_PB=''
_PS='0fd9271b89220e096bb08e2db2ff3b3523b32664646da30789a796cf9be20c45'
_AB=''
ATLAS_SHA='e1b755dbe98217cd8bec59de7f74488eb4220a9e3125bb9071f21384967ee0c6'

LADDER=["0.5b-instruct/1","1.5b-instruct/1","3b-instruct/1","7b-instruct/1"]
dev="cuda"
PRB=[["天台对峙", "两人上天台时，水塔先滴了一声。"], ["德洛丽丝线", "她把同一杯咖啡倒了第365次，今天杯柄朝向了自已。"], ["观星台", "望远镜还没冷却，银河已经挪过一格。"], ["火锅局", "毛肚在锅底数着秒，汤却喊了第二遍滚。"], ["钓鱼塘", "雨天塘口更冷清，浮漂都长了青苔。"], ["修表台", "发条太细，师傅戴着放大镜也读不懂心跳。"], ["海关查验", "X光带走慢半拍，屏后的 Officer 放下了咖啡。"], ["庙会", "香火绕了三圈才凉，殿前石狮子还亮着。"], ["长途绿皮车", "夜皮车连跨四个时区，下铺的暖壶还剩半壶早晨。"], ["快递驿站", "取件码念到第99遍，柜台后的姑娘抬头记得她还是那个地址。"], ["急诊分诊", "号票还没落定，轮椅先往前走两个号位。"], ["ANCHOR", "Coffee is warming, sun is rising."]]
A=json.loads(base64.b64decode(_AB))
def run_ladder():
    out={}
    for rel in LADDER:
        mnt="/kaggle/input/models/qwen-lm/qwen2.5/transformers/"+rel.replace("/4bit","")
        kw={"dtype":torch.float16}
        if False:
            from transformers import BitsAndBytesConfig
            kw={"quantization_config":BitsAndBytesConfig(load_in_4bit=True,bnb_4bit_compute_dtype=torch.float16,bnb_4bit_quant_type="nf4"),
                "device_map":"auto"}; 
        try:
            tok=AutoTokenizer.from_pretrained(mnt)
            model=AutoModelForCausalLM.from_pretrained(mnt,**kw).eval()
        except Exception as e:
            out[rel]={"error":str(e)[:110]}; continue
        if "4bit" not in rel: model=model.to(dev)
        def emb(t):
            e=tok(t,add_special_tokens=False,return_tensors="pt").to(dev)
            with torch.no_grad(): h=model.model(**e).last_hidden_state[0].float().cpu().numpy()
            return h.mean(0) if "qwen" in rel or True else None
        tokv={}; V=[]
        for s in A["spaces"]:
            for t in s["tokens"]:
                V.append(emb(t["token"]+f"（{s['domain']}·{s['concept_space']}）"))
        MUn=np.vstack(V).mean(0)
        def u(v):
            w=v-MUn; return w/(np.linalg.norm(w)+1e-9)
        cent={}; i0=0
        for s in A["spaces"]:
            n=len(s["tokens"]); vs=np.stack([u(x) for x in V[i0:i0+n]]); i0+=n
            c=vs.mean(0); cent[s["concept_space"]]=c/(np.linalg.norm(c)+1e-9)
        names=list(cent); CM=np.stack([cent[x] for x in names])
        rows=[]
        for tgt,sent in PRB:
            v=u(emb(sent)); sc=CM@v
            order=np.argsort(-sc); top=[(names[k],round(float(sc[k]),4)) for k in order[:5]]
            r={"sent":sent,"top5":top}
            if tgt!="ANCHOR":
                k=int(np.where(np.array(names)==tgt)[0][0]); r["rank_target"]=int(np.where(order==k)[0][0])+1
            rows.append(r)
        hit=[r for r in rows if "rank_target" in r]
        out[rel]={"top3_frac":round(sum(r["rank_target"]<=3 for r in hit)/len(hit),3),
                  "mean_rank":round(float(np.mean([r["rank_target"] for r in hit])),2),
                  "anchor_top5":next(r["top5"] for r in rows if "target" not in r),
                  "rows":rows,"probe_min":round((time.time()-t0)/60,1)}
        del model,tok; import gc; gc.collect(); torch.cuda.empty_cache()
        print(rel,"done",flush=True)
    return out
t0=time.time()
res={"exp":"17-freshprobe","prereg":"fresh句=词知组合未见; 判据: target 空间进 top3 视为固有激活; 阶梯看激活密度vs规模",
     "ladder":run_ladder(),"minutes":round((time.time()-t0)/60,1)}
json.dump(res,open("/kaggle/working/report_exp17.json","w"),ensure_ascii=False)
print("REPORT_LINE",base64.b64encode(json.dumps(res).encode()).decode())
